      sentence = "In a place like this where countless meetings, reunions, and partings took place daily, the stories always had intense emotions lurking in the background amplified by distance and uncertainty...",
      next = {13}
    },
    [13] = {
      beijing = 2250,
      dialog = 3,
      music = "52_Daily03",
      renwu = "npc",
      sentence = "...which was precisely the reason we wanted to film here on Valentine's Day.",
