      dialog = 2,
      idx = 5,
      music = "52_Daily03",
      renming = "Passerby A",
      renwu = "npc",
      sentence = "Profess my feelings? I think that's a pretty important thing. I specifically chose today to come back and tell this girl that I love her!",
