    },
    [15] = {
      beijing = 2250,
      dialog = 2,
      idx = 5,
      music = "52_Daily03",
      renming = "Passerby B",
      renwu = "npc",
      sentence = "Every time I see my boyfriend again after we've been apart, I always tell him, \"I've missed you so.\" I think that's the best way to show my love.",
