    [16] = {
      beijing = 2250,
      dialog = 2,
      idx = 5,
      music = "52_Daily03",
      renming = "Passerby C",
      renwu = "npc",
      sentence = "When you love someone, you just know it. And showing it is the same way. If someone's come all this way to see you, just one look in their eyes tells you all you need to know.",
