      role3 = 4193203,
      role5 = 4193401,
      roleanim = 1.1,
      sentence = "Ever since regaining consciousness, I'd had one bombshell after another dropped on me. My thoughts were a hopeless jumble, to say nothing of trying to string a sentence together.",
