      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      roleanim = 1.1,
      sentence = "I looked into the stern and dignified face of the young noble before me. In all my muddled thoughts, at least one thing was clear.",
