      role2 = 4193111,
      role3 = 4193203,
      role5 = 4193401,
      roleanim = 1.1,
      sentence = "Besides, being able to keep my soul intact and have such a strikingly handsome water ghost for a husband was actually... pretty good no matter how I sliced it.",
