    [88] = {
      beijing = 4996,
      dialog = 3,
      music = "27_Double_Seventh",
      renwu = "npc",
      sentence = "Like a wooden wedge finding the hole it was meant to fill, a desperately scorching aura seemed to entangle itself with my soul as our breaths mingled.",
