    },
    [96] = {
      beijing = 4996,
      dialog = 3,
      music = "27_Double_Seventh",
      renwu = "npc",
      sentence = "Meanwhile, every limb of my body was overrun by an imposing ghostly presence until it felt like I was transformed into a rushing tide.",
