      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      sentence = "The imposing timbre of his voice was shudder-inducing, but for some reason, I wasn't afraid of him.",
