      renming = "$u",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      sentence = "...You speak the truth. But even though I was looked down on by the village from a young age, all they really did was keep their distance from me. I never thought they'd want to kill me.",
      next = {114}
    },
    [114] = {
      beijing = 4630,
      dhead = 105,
      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      sentence = "They may not be goodhearted, but they're not innately treacherous either. If things would've remained peaceful, I probably never would've been made a ghost bride.",
      next = {115}
    },
    [115] = {
      beijing = 4630,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194107,
      role3 = 4194206,
      role5 = 4194401,
      sentence = "I closed my eyes, and my mind flashed with rising floodwaters, homes being washed away, and that matchmaker's face as she looked away from me...",
      next = {116}
    },
    [116] = {
      beijing = 4630,
      dhead = 105,
      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      sentence = "They couldn't survive, so their only hope was to turn to the ghost realm... and get blood on their hands.",
      next = {117}
    },
    [117] = {
      beijing = 4630,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      sentence = "I muttered to myself and let out a sigh.",
      next = {118}
    },
    [118] = {
      beijing = 4630,
