      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      sentence = "Perhaps, in all my years as an exorcist, I've seen too much of this kind of thing. Instead of hate, what I feel more is just resignation, that's all.",
      next = {119}
    },
    [119] = {
      beijing = 4630,
