      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      roleanim = 1.1,
      sentence = "Gavin's expression was muted and stoic. He reached up and caught a tress of my hair, pulling me to lean on him.",
      next = {120}
    },
    [120] = {
      beijing = 4630,
      dialog = 2,
      idx = 4,
