      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194206,
      role5 = 4194401,
      roleanim = 1.1,
      sentence = "Even if they're victims, even if they're ignorant, they're still murderers—and I, a \"wraith\", am the one that saved you.",
      voice = 2,
